def descer(v, i, n):
    while 2 * i + 1 < n:
        f = 2 * i + 1
        if f + 1 < n and v[f + 1] > v[f]:
            f += 1
        if v[i] >= v[f]:
            break
        v[i], v[f] = v[f], v[i]
        i = f

v = [3, 5, 9, 6, 8, 20, 10]
for i in range(len(v) // 2 - 1, -1, -1):
    descer(v, i, len(v))
print(v)

